set-variable.value:
@{
    if (context.Request.Method != "POST") { return ""; }
    var body = context.Request.Body?.As<string>(true) ?? "";
    if (body.Length == 0) { return ""; }
    JToken root;
    try { root = JToken.Parse(body); } catch { return ""; }
    var messages = root is JArray ? (JArray)root : new JArray(root);
    var exposed = context.Variables.GetValueOrDefault<string>("tool-names", "").Split('|');
    foreach (var m in messages) {
      if (m.Type == JTokenType.Object && (string)m["method"] == "tools/call") {
        var name = (string)m.SelectToken("params.name") ?? "";
        if (!exposed.Contains(name)) { return name.Length == 0 ? "(none)" : name; }
      }
    }
    return "";
  }

return-response.set-body:
@{
          JToken id = null;
          try { var r = JToken.Parse(context.Request.Body.As<string>(true)); id = (r is JArray ? r.First : r)["id"]; } catch { }
          return new JObject(
            new JProperty("jsonrpc", "2.0"),
            new JProperty("id", id),
            new JProperty("error", new JObject(
              new JProperty("code", -32602),
              new JProperty("message", "TOOL_NOT_ALLOWED: tool " + context.Variables.GetValueOrDefault<string>("tool-refused") + " is not exposed by " + context.Variables.GetValueOrDefault<string>("project", "") + "/" + context.Variables.GetValueOrDefault<string>("tool", "") + " on this gateway.")))).ToString();
        }
